[{"category":"section","location":"goesr/#Geostationary-Operational-Environmental-Satellites-(GOES)","page":"GOES-R Example","text":"Example for reading and plotting GOES-R data","title":"Geostationary Operational Environmental Satellites (GOES)"},{"category":"section","location":"goesr/#Basic-Usage","page":"GOES-R Example","text":"using SpaceWeather\nusing SpaceWeather.GOES\nusing Dates\n\n# Download and load XRS data for a single day\nxrs = GOES.XRS[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\n\n# Access X-ray flux data\nxrsa = xrs[\"xrsa_flux\"]  # Short wavelength (0.05-0.4 nm)\nxrsb = xrs[\"xrsb_flux\"]  # Long wavelength (0.1-0.8 nm)\nView:  1:1440\n\u001b[32m xrsb_flux\u001b[39m  (1440)\n   Datatype:    \u001b[0m\u001b[1mUnion{Missing, Float32}\u001b[22m\n   Dimensions:  time\n   Attributes:\n    _FillValue           = \u001b[36m-9999.0\u001b[39m\n    long_name            = \u001b[36mXRS-B primary average flux.\u001b[39m\n    comments             = \u001b[36mElectron contamination has been removed. xrsb_flux =  xrsb_flux_observed - xrsb_flux_electrons\u001b[39m\n    units                = \u001b[36mW/m2\u001b[39m\n    valid_min            = \u001b[36m1.0e-9\u001b[39m\n    valid_max            = \u001b[36m0.2\u001b[39m\n    ancillary_variables  = \u001b[36mxrsb_flag xrsb_num xrsb_flag_excluded electron_correction_flag\u001b[39m\n\n\n# load Magnetospheric Particle Sensor High (MPS-HI)\nmpsh_ds = GOES.MPSH[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\nmpsh_ds[\"AvgDiffProtonFlux\"]\nView:  Base.Slice(Base.OneTo(11)) × Base.Slice(Base.OneTo(5)) × 1:1440\n\u001b[32m AvgDiffProtonFlux\u001b[39m  (11 × 5 × 1440)\n   Datatype:    \u001b[0m\u001b[1mUnion{Missing, Float32}\u001b[22m\n   Dimensions:  proton_diff_chans × telescopes × time\n   Attributes:\n    _FillValue           = \u001b[36m-1.0e31\u001b[39m\n    long_name            = \u001b[36mTime-averaged proton fluxes in several differential channels between 80 and 10,000 keV\u001b[39m\n    units                = \u001b[36mprotons/(cm^2 sr keV s)\u001b[39m\n    valid_min            = \u001b[36m0.0\u001b[39m\n    valid_max            = \u001b[36m460000.0\u001b[39m\n\n\n# load MAG Data\nmag_ds = GOES.MAG[id = 16](Date(2020, 6, 1), Date(2020, 6, 2))\nmag_ds[\"b_total\"]\nView:  1:1440\n\u001b[32m b_total\u001b[39m  (1440)\n   Datatype:    \u001b[0m\u001b[1mUnion{Missing, Float32}\u001b[22m\n   Dimensions:  time\n   Attributes:\n    _FillValue           = \u001b[36m-9999.0\u001b[39m\n    long_name            = \u001b[36mmagnetic_field_total_magnitude\u001b[39m\n    comments             = \u001b[36mEstimated ambient magnetic field in ACRF coordinates (total).\u001b[39m\n    units                = \u001b[36mnT\u001b[39m\n    valid_min            = \u001b[36m0.0\u001b[39m\n    valid_max            = \u001b[36m1024.0\u001b[39m\n","title":"Basic Usage"},{"category":"section","location":"goesr/#Plotting-GOES-R-XRS-Data","page":"GOES-R Example","text":"using CairoMakie\n\nf = Figure()\nax1 = Axis(f[1, 1]; yscale = log10, xlabel = \"Time (UTC)\", ylabel = \"X-Ray Flux\\n($(xrsa.attrib[\"units\"]))\")\ntimes = nomissing(xrs[\"time\"][:])\nlines!(ax1, times, nomissing(xrsa[:]); label = \"GOES-16 XRS-A (0.05-0.4 nm)\", color = :mediumorchid)\nlines!(ax1, times, nomissing(xrsb[:]); label = \"GOES-16 XRS-B (0.1-0.8 nm)\", color = :green)\n\n# Plot 1 day of MPSH 1-minute AvgDiffProtonFlux in Telescope 0, Band 0\nvar = mpsh_ds[\"AvgDiffProtonFlux\"]\nax2 = Axis(f[2, 1]; yscale = log10, xlabel = \"Time (UTC)\", ylabel = \"AvgDiffProtonFlux\\n($(var.attrib[\"units\"]))\")\ntimes = nomissing(mpsh_ds[\"time\"][:])\nlines!(ax2, times, var[1, 1, :])\n\nvar = mag_ds[\"b_total\"]\nax3 = Axis(f[3, 1]; ylabel = \"b_total\\n($(var.attrib[\"units\"]))\")\ntimes = nomissing(mag_ds[\"time\"][:])\nlines!(ax3, times, var[:])\n\nhidexdecorations!.((ax1, ax2); grid = false)\nf\nFigure()","title":"Plotting GOES-R XRS Data"},{"category":"section","location":"#SpaceWeather","page":"Home","text":"Usage is in the README.\n\nusing SpaceWeather\nKp(\"2024-05-10\", \"2024-05-13\")\nSpaceDataModel.DataVariable{Float64, 1, 1, Vector{Float64}, Vector{Dates.DateTime}, Dict{String, Any}}: \u001b[38;5;37mKp\u001b[39m\n  Time Range: 2024-05-10T00:00:00 to 2024-05-12T21:00:00\n  Units: 1\n  Size: (24,)\n  Memory Usage: 1.090 KiB\n  Metadata:\n    source: https://kp.gfz.de\n    cadence: PT3H\n    doi: 10.5880/Kp.0001\n    units: 1","title":"SpaceWeather"},{"category":"section","location":"#API-Reference","page":"Home","text":"","title":"API Reference"},{"category":"module","location":"#SpaceWeather.GOES","page":"Home","text":"Geostationary Operational Environmental Satellites\n\nR Series | NOAA/NASA: https://www.goes-r.gov/\nData Source: https://data.ngdc.noaa.gov/platforms/solar-space-observing-satellites/goes/\nDocumentation: https://www.ngdc.noaa.gov/stp/satellite/goes-r.html\nCatalog: https://catalog.data.gov/dataset/geostationary-operational-environmental-satellite-r-series-goes-r-space-environment-in-situ-sui2\nSEISS Documentation: https://www.ncei.noaa.gov/products/goes-r-space-environment-in-situ\n\n\n\n\n\n","title":"SpaceWeather.GOES"},{"category":"constant","location":"#SpaceWeather.GOES.MAG","page":"Home","text":"Magnetometer (MAG)\n\n\n\n\n\n","title":"SpaceWeather.GOES.MAG"},{"category":"constant","location":"#SpaceWeather.GOES.MPSH","page":"Home","text":"Magnetospheric Particle Sensor High (MPS-HI)\n\n\n\n\n\n","title":"SpaceWeather.GOES.MPSH"},{"category":"constant","location":"#SpaceWeather.GOES.SGPS","page":"Home","text":"Solar and Galactic Proton Sensor (SGPS)\n\n\n\n\n\n","title":"SpaceWeather.GOES.SGPS"},{"category":"constant","location":"#SpaceWeather.GOES.XRS","page":"Home","text":"X-Ray Sensor (XRS)\n\nGOES X-ray plots\n\ngetdata(XRS[id = 16], Date(2020, 6, 1), Date(2020, 6, 3))[\"xrsa_flux\"]\n\n\n\n\n\n","title":"SpaceWeather.GOES.XRS"}]
